const config = {
  "previewFeatures": [
    "prismaSchemaFolder",
    "views"
  ],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// File removed: content migrated to separate schema files\n\n// ============================================================\n// SAF - Sistema de Administracion de Flotas\n// Manual F1T02 — Procedimientos Basicos de Operacion y Control\n// Archivo: base.prisma — Generadores, fuente de datos y configuracion\n// ============================================================\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../../generated/prisma\"\n  previewFeatures = [\"views\", \"prismaSchemaFolder\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: conductores.prisma â€” Esquema de Conductores y Personal\n// ============================================================\n\n/// Personal del sistema de flotas F1T02 con roles jerÃ¡rquicos segÃºn organigrama\nmodel Usuario {\n  id                  String     @id @default(uuid())\n  nombre              String     @db.VarChar(100)\n  apellido            String     @db.VarChar(100)\n  email               String     @unique @db.VarChar(150)\n  password            String?    @db.VarChar(255)\n  rol                 RolUsuario @default(ADMINISTRATIVO)\n  activo              Boolean    @default(true)\n  telefono            String?    @db.VarChar(20)\n  /// NÃºmero de licencia de conducir (requerido para conductores)\n  licenciaConducir    String?    @map(\"licencia_conducir\") @db.VarChar(30)\n  /// CategorÃ­a de licencia (A, B, C, D â€” requerida para conductores)\n  categoriaLicencia   String?    @map(\"categoria_licencia\") @db.VarChar(5)\n  /// Fecha de vencimiento de la licencia\n  vencimientoLicencia DateTime?  @map(\"vencimiento_licencia\")\n  /// Especialidad tÃ©cnica (para mecÃ¡nicos y electricistas)\n  especialidad        String?    @db.VarChar(100)\n  ultimoAcceso        DateTime?  @map(\"ultimo_acceso\")\n  creadoEn            DateTime   @default(now()) @map(\"creado_en\")\n  actualizadoEn       DateTime   @updatedAt @map(\"actualizado_en\")\n  bloqueadoHasta      DateTime?  @map(\"bloqueado_hasta\")\n  intentosFallidos    Int        @default(0) @map(\"intentos_fallidos\")\n\n  // Relaciones\n  permisos             PermisoUsuario[]\n  sesionesAuth         SesionAuth[]\n  auditoria            Auditoria[]\n  tokensConfirmacion   TokenConfirmacion[]\n  movimientosDiarios   MovimientoDiario[]   @relation(\"ConductorMovimiento\")\n  revisionesChecklist  MovimientoDiario[]   @relation(\"InspectorMovimiento\")\n  ordenesCombustible   OrdenCombustible[]\n  ordenesMantenimiento OrdenMantenimiento[]\n  asignaciones         AsignacionVehiculo[]\n  programaciones       ProgramacionRuta[]\n\n  @@index([rol])\n  @@index([activo])\n  @@map(\"usuarios\")\n}\n\n/// Roles jerárquicos del organigrama F1T02 (13 roles)\n/// JEFE_PROCESO: máxima autoridad del proceso de gestión de flotas\n///\n/// Equipo de Operación:\n///   JEFE_OPERACION, ENCARGADO_GARAJE, INSPECTOR, CONTROLADOR_TRANSITO, ANALISTA, CONDUCTOR\n///\n/// Equipo de Mantenimiento:\n///   JEFE_MANTENIMIENTO, ENCARGADO_TALLER, MECANICO, ELECTRICISTA, REENCAUCHADOR, LAVADOR\n///\n/// Apoyo Administrativo:\n///   ADMINISTRATIVO\nenum RolUsuario {\n  // General\n  JEFE_PROCESO\n\n  // Equipo de Operación\n  JEFE_OPERACION\n  ENCARGADO_GARAJE\n  INSPECTOR\n  CONTROLADOR_TRANSITO\n  ANALISTA\n  CONDUCTOR\n\n  // Equipo de Mantenimiento\n  JEFE_MANTENIMIENTO\n  ENCARGADO_TALLER\n  MECANICO\n  ELECTRICISTA\n  REENCAUCHADOR\n  LAVADOR\n\n  // Apoyo Administrativo\n  ADMINISTRATIVO\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: configuracion.prisma â€” Esquema de ConfiguraciÃ³n General\n// ============================================================\n\n/// ParÃ¡metros generales del sistema SAF (nombre de la unidad, metas de km, etc.)\nmodel ConfiguracionFlota {\n  id            String   @id @default(uuid())\n  clave         String   @unique @db.VarChar(100)\n  valor         String\n  descripcion   String?\n  grupo         String   @default(\"general\") @db.VarChar(50)\n  creadoEn      DateTime @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime @updatedAt @map(\"actualizado_en\")\n\n  @@map(\"configuracion_flota\")\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: control_combustible.prisma â€” Esquema de Control de Combustible\n// ============================================================\n\n/// Orden de abastecimiento de combustible y lubricantes â€” MA 122 01 02\nmodel OrdenCombustible {\n  id                String               @id @default(uuid())\n  /// NÃºmero de orden correlativo\n  numeroOrden       String               @unique @map(\"numero_orden\") @db.VarChar(20)\n  fecha             DateTime             @db.Date\n  vehiculoId        String               @map(\"vehiculo_id\")\n  conductorId       String               @map(\"conductor_id\")\n  sectorSolicitante String               @map(\"sector_solicitante\") @db.VarChar(150)\n  tipoCombustible   TipoCombustibleOrden @map(\"tipo_combustible\")\n\n  // â”€â”€ Combustible â”€â”€\n  cantidadGalones  Decimal? @map(\"cantidad_galones\") @db.Decimal(8, 2)\n  costoGalon       Decimal? @map(\"costo_galon\") @db.Decimal(8, 3)\n  costoCombustible Decimal? @map(\"costo_combustible\") @db.Decimal(10, 2)\n\n  // â”€â”€ Lubricante â€” Aceite de Motor (registrado por separado) â”€â”€\n  /// Indica si esta orden incluye cambio/adiciÃ³n de aceite de motor\n  incluyeAceiteMotor    Boolean  @default(false) @map(\"incluye_aceite_motor\")\n  cantidadAceiteMotorLt Decimal? @map(\"cantidad_aceite_motor_lt\") @db.Decimal(6, 2)\n  marcaAceiteMotor      String?  @map(\"marca_aceite_motor\") @db.VarChar(80)\n  viscosidadAceiteMotor String?  @map(\"viscosidad_aceite_motor\") @db.VarChar(20)\n  costoAceiteMotor      Decimal? @map(\"costo_aceite_motor\") @db.Decimal(10, 2)\n\n  // â”€â”€ Lubricante â€” Aceite de Caja/TransmisiÃ³n (registrado por separado) â”€â”€\n  /// Indica si esta orden incluye cambio de aceite de caja\n  incluyeAceiteCaja    Boolean  @default(false) @map(\"incluye_aceite_caja\")\n  cantidadAceiteCajaLt Decimal? @map(\"cantidad_aceite_caja_lt\") @db.Decimal(6, 2)\n  marcaAceiteCaja      String?  @map(\"marca_aceite_caja\") @db.VarChar(80)\n  viscosidadAceiteCaja String?  @map(\"viscosidad_aceite_caja\") @db.VarChar(20)\n  costoAceiteCaja      Decimal? @map(\"costo_aceite_caja\") @db.Decimal(10, 2)\n\n  // â”€â”€ Costo Total de la Orden â”€â”€\n  costoTotal Decimal @default(0) @map(\"costo_total\") @db.Decimal(12, 2)\n\n  // â”€â”€ OdÃ³metro al momento del abastecimiento â”€â”€\n  kilometrajeActual Int @map(\"kilometraje_actual\")\n\n  // â”€â”€ Datos del Servicentro Acreditado â”€â”€\n  nombreServiccentro       String? @map(\"nombre_serviccentro\") @db.VarChar(150)\n  direccionServiccentro    String? @map(\"direccion_serviccentro\")\n  /// NÃºmero de ticket o factura del servicentro\n  numeroTicketServiccentro String? @map(\"numero_ticket_serviccentro\") @db.VarChar(50)\n  /// Nombre del responsable que firma/sella en el servicentro\n  responsableServiccentro  String? @map(\"responsable_serviccentro\") @db.VarChar(100)\n  /// Indica si se recibiÃ³ el sello del servicentro\n  selloServiccentro        Boolean @default(false) @map(\"sello_serviccentro\")\n\n  // â\"€â\"€ Solicitante â\"€â\"€\n  /// Localidad donde estÃ¡ ubicado el sector del solicitante\n  localidadSolicitante String? @map(\"localidad_solicitante\") @db.VarChar(150)\n\n  // â\"€â\"€ Firmas (MA 122 01 02 - F1T02) â\"€â\"€\n  /// Firma del Encargado del Garaje\n  firmaEncargadoGaraje String? @map(\"firma_encargado_garaje\") @db.VarChar(100)\n  /// Firma del Conductor del vehÃ­culo\n  firmaConductor       String? @map(\"firma_conductor\") @db.VarChar(100)\n  /// Firma del Representante del Servicentro\n  firmaServicentro     String? @map(\"firma_servicentro\") @db.VarChar(100)\n\n  observaciones String?\n  creadoEn      DateTime @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime @updatedAt @map(\"actualizado_en\")\n\n  vehiculo  Vehiculo @relation(fields: [vehiculoId], references: [id], onDelete: Restrict)\n  conductor Usuario  @relation(fields: [conductorId], references: [id], onDelete: Restrict)\n\n  @@index([vehiculoId])\n  @@index([vehiculoId, fecha])\n  @@index([conductorId])\n  @@index([fecha])\n  @@index([numeroOrden])\n  @@map(\"ordenes_combustible\")\n}\n\n/// Tipo de combustible o lubricante en la orden de abastecimiento\nenum TipoCombustibleOrden {\n  GASOLINA\n  DIESEL\n  GLP\n  ACEITE_MOTOR\n  ACEITE_CAJA\n  MIXTO\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: control_costos.prisma â€” Esquema de Control de Costos (Fijos y Consolidado)\n// ============================================================\n\n/// Costos fijos del Ã¡rea que se prorratean en el CKV (personal, oficina, etc.)\nmodel CostoFijoProrrateable {\n  id            String        @id @default(uuid())\n  periodo       String        @db.VarChar(7)\n  tipo          TipoCostoFijo\n  descripcion   String        @db.VarChar(255)\n  montoMensual  Decimal       @map(\"monto_mensual\") @db.Decimal(12, 2)\n  activo        Boolean       @default(true)\n  creadoEn      DateTime      @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime      @updatedAt @map(\"actualizado_en\")\n\n  @@index([periodo])\n  @@index([tipo])\n  @@map(\"costos_fijos_prorrateables\")\n}\n\n/// Tipos de costos fijos prorrateables para el cÃ¡lculo CKV\nenum TipoCostoFijo {\n  PERSONAL_ADMINISTRATIVO\n  OFICINA\n  COMUNICACIONES\n  SEGUROS_GENERALES\n  LICENCIAS_SOFTWARE\n  OTROS\n}\n\n/// Vista de base de datos para el reporte consolidado de costos operacionales mensuales por vehÃ­culo\nview ReporteMensualCostos {\n  /// Identificador Ãºnico (ficticio o real) requerido para Prisma Client\n  id                   String  @unique\n  vehiculoId           String  @map(\"vehiculo_id\")\n  periodo              String  @db.VarChar(7) // Formato: YYYY-MM\n  costoCombustible     Decimal @map(\"costo_combustible\") @db.Decimal(12, 2)\n  costoMantenimiento   Decimal @map(\"costo_mantenimiento\") @db.Decimal(12, 2)\n  costoFijoProrrateado Decimal @map(\"costo_fijo_prorrateado\") @db.Decimal(12, 2)\n  costoTotal           Decimal @map(\"costo_total\") @db.Decimal(12, 2)\n\n  vehiculo Vehiculo @relation(fields: [vehiculoId], references: [id])\n\n  @@map(\"v_reporte_mensual_costos\")\n}\n\n/// Vista analÃ­tica consolidada de KPIs de rendimiento y coste por vehÃ­culo\nview ResumenKpisVehiculo {\n  id                 String  @unique\n  vehiculoId         String  @map(\"vehiculo_id\")\n  marca              String\n  modelo             String\n  placa              String\n  kilometrajeTotal   Int     @map(\"kilometraje_total\")\n  horasUtilizacion   Decimal @map(\"horas_utilizacion\") @db.Decimal(10, 2)\n  galonesCombustible Decimal @map(\"galones_combustible\") @db.Decimal(10, 2)\n  costoCombustible   Decimal @map(\"costo_combustible\") @db.Decimal(12, 2)\n  costoMantenimiento Decimal @map(\"costo_mantenimiento\") @db.Decimal(12, 2)\n  viajesRealizados   Int     @map(\"viajes_realizados\")\n\n  vehiculo Vehiculo @relation(fields: [vehiculoId], references: [id])\n\n  @@map(\"v_resumen_kpis_vehiculo\")\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: control_llantas.prisma â€” Esquema de Control de Llantas\n// ============================================================\n\n/// Control individualizado de llantas: cÃ³digo EPS, posiciÃ³n, kilometraje acumulado\nmodel ControlLlanta {\n  id                     String       @id @default(uuid())\n  /// CÃ³digo Ãºnico de la llanta (NÃºmero EPS del fabricante)\n  codigoEps              String       @unique @map(\"codigo_eps\") @db.VarChar(50)\n  vehiculoId             String       @map(\"vehiculo_id\")\n  fabricante             String       @db.VarChar(80)\n  dimension              String       @db.VarChar(30)\n  modeloLlanta           String       @map(\"modelo_llanta\") @db.VarChar(80)\n  /// PosiciÃ³n en el vehÃ­culo segÃºn diagrama del manual (1â€“7)\n  posicionVehiculo       Int          @map(\"posicion_vehiculo\")\n  /// DescripciÃ³n textual de la posiciÃ³n (ej. \"Delantera Izquierda\")\n  descripcionPosicion    String?      @map(\"descripcion_posicion\") @db.VarChar(50)\n  estado                 EstadoLlanta @default(EN_USO)\n  fechaInstalacion       DateTime     @map(\"fecha_instalacion\")\n  fechaRetiro            DateTime?    @map(\"fecha_retiro\")\n  /// Kilometraje del vehÃ­culo al momento de instalar la llanta\n  kilometrajeInstalacion Int          @map(\"kilometraje_instalacion\")\n  /// Kilometraje del vehÃ­culo al momento de retirar la llanta\n  kilometrajeRetiro      Int?         @map(\"kilometraje_retiro\")\n  /// Km recorridos con esta llanta = kmRetiro - kmInstalacion\n  kilometrajeAcumulado   Int          @default(0) @map(\"kilometraje_acumulado\")\n  /// NÃºmero de veces que ha sido reencauchada\n  vecesReencauchada      Int          @default(0) @map(\"veces_reencauchada\")\n  /// Costo de adquisiciÃ³n de la llanta\n  costoAdquisicion       Decimal?     @map(\"costo_adquisicion\") @db.Decimal(10, 2)\n  observaciones          String?\n  creadoEn               DateTime     @default(now()) @map(\"creado_en\")\n  actualizadoEn          DateTime     @updatedAt @map(\"actualizado_en\")\n  vehiculo               Vehiculo     @relation(fields: [vehiculoId], references: [id], onDelete: Restrict)\n\n  @@index([vehiculoId])\n  @@index([estado])\n  @@index([codigoEps])\n  @@index([fechaInstalacion])\n  @@index([posicionVehiculo])\n  @@map(\"control_llantas\")\n}\n\n/// Estado de una llanta segÃºn su ciclo de vida\nenum EstadoLlanta {\n  EN_USO\n  EN_ALMACEN\n  REENCAUCHADA\n  EN_REENCAUCHE\n  DADA_DE_BAJA\n}\n\n/// Vista analÃ­tica de desempeÃ±o y coste por kilÃ³metro de neumÃ¡ticos\nview DesempenoLlantas {\n  id                   String   @unique\n  codigoEps            String   @map(\"codigo_eps\")\n  vehiculoId           String   @map(\"vehiculo_id\")\n  fabricante           String\n  kilometrajeAcumulado Int      @map(\"kilometraje_acumulado\")\n  vecesReencauchada    Int      @map(\"veces_reencauchada\")\n  costoAdquisicion     Decimal? @map(\"costo_adquisicion\") @db.Decimal(10, 2)\n  costoPorKm           Decimal? @map(\"costo_por_km\") @db.Decimal(10, 4)\n\n  vehiculo Vehiculo @relation(fields: [vehiculoId], references: [id])\n\n  @@map(\"v_desempeno_llantas\")\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: control_mantenimiento.prisma â€” Esquema de Control de Mantenimiento\n// ============================================================\n\n/// Orden de mantenimiento preventivo o correctivo â€” MA 122 02 01\nmodel OrdenMantenimiento {\n  id                String            @id @default(uuid())\n  /// NÃºmero de orden correlativo de mantenimiento\n  numeroOrden       String            @unique @map(\"numero_orden\") @db.VarChar(20)\n  fechaEmision      DateTime          @map(\"fecha_emision\") @db.Date\n  vehiculoId        String            @map(\"vehiculo_id\")\n  /// TÃ©cnico responsable de ejecutar el mantenimiento\n  tecnicoId         String?           @map(\"tecnico_id\")\n  sectorSolicitante String            @map(\"sector_solicitante\") @db.VarChar(150)\n  tipoMantenimiento TipoMantenimiento @map(\"tipo_mantenimiento\")\n\n  // â”€â”€ Tipo de Taller â”€â”€\n  /// Origen del servicio: Taller Propio (con Tarjeta de Mano de Obra)\n  /// o Taller de Terceros (con AutorizaciÃ³n de Servicio Externo)\n  tipoTaller                TipoTaller @map(\"tipo_taller\")\n  /// Nombre del taller de terceros (si aplica)\n  nombreTallerExterno       String?    @map(\"nombre_taller_externo\") @db.VarChar(150)\n  /// NÃºmero de autorizaciÃ³n de servicio externo (si aplica)\n  numeroAutorizacionExterna String?    @map(\"numero_autorizacion_externa\") @db.VarChar(50)\n\n  // â”€â”€ Entrada y Salida del Taller â”€â”€\n  fechaEntradaTaller DateTime? @map(\"fecha_entrada_taller\") @db.Date\n  horaEntradaTaller  String?   @map(\"hora_entrada_taller\") @db.VarChar(5)\n  fechaSalidaTaller  DateTime? @map(\"fecha_salida_taller\") @db.Date\n  horaSalidaTaller   String?   @map(\"hora_salida_taller\") @db.VarChar(5)\n\n  // â”€â”€ OdÃ³metro â”€â”€\n  kilometrajeEntrada Int? @map(\"kilometraje_entrada\")\n  kilometrajeSalida  Int? @map(\"kilometraje_salida\")\n\n  // â”€â”€ DescripciÃ³n del Servicio â”€â”€\n  descripcionServicio String\n  /// Falla reportada por el conductor (para correctivo)\n  fallaReportada      String? @map(\"falla_reportada\")\n  /// DiagnÃ³stico del tÃ©cnico\n  diagnosticoTecnico  String? @map(\"diagnostico_tecnico\")\n\n  // â”€â”€ Desglose de Costos (Taller Propio) â”€â”€\n  /// Costo de mano de obra propia (en base a Tarjeta de Mano de Obra)\n  costoManoObraPropia   Decimal? @map(\"costo_mano_obra_propia\") @db.Decimal(12, 2)\n  /// Costo de mano de obra de terceros (factura del taller externo)\n  costoManoObraTerceros Decimal? @map(\"costo_mano_obra_terceros\") @db.Decimal(12, 2)\n  /// Costo total de piezas y repuestos del AlmacÃ©n de Mantenimiento\n  costoPiezasRepuestos  Decimal? @default(0) @map(\"costo_piezas_repuestos\") @db.Decimal(12, 2)\n  /// Otros costos (traslado, peritaje, etc.)\n  costoOtros            Decimal? @default(0) @map(\"costo_otros\") @db.Decimal(12, 2)\n  /// Costo total de la orden (calculado: MO + Piezas + Otros)\n  costoTotal            Decimal? @map(\"costo_total\") @db.Decimal(12, 2)\n\n  // Firmas Digitales\n  firmaEncargadoTaller   String?   @map(\"firma_encargado_taller\") @db.VarChar(100)\n  firmaTecnico           String?   @map(\"firma_tecnico\") @db.VarChar(100)\n  firmaJefeMantenimiento String?   @map(\"firma_jefe_mantenimiento\") @db.VarChar(100)\n  fechaFirmaTecnico      DateTime? @map(\"fecha_firma_tecnico\")\n\n  // â”€â”€ Estado â”€â”€\n  estado        EstadoMantenimiento @default(PENDIENTE)\n  observaciones String?\n  creadoEn      DateTime            @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime            @updatedAt @map(\"actualizado_en\")\n\n  // â”€â”€ Relaciones â”€â”€\n  vehiculo   Vehiculo          @relation(fields: [vehiculoId], references: [id], onDelete: Restrict)\n  tecnico    Usuario?          @relation(fields: [tecnicoId], references: [id], onDelete: Restrict)\n  repuestos  DetalleRepuesto[]\n  manoDeObra DetalleManoObra[]\n\n  @@index([vehiculoId])\n  @@index([vehiculoId, fechaEmision])\n  @@index([tipoMantenimiento])\n  @@index([tipoTaller])\n  @@index([estado])\n  @@index([fechaEmision])\n  @@map(\"ordenes_mantenimiento\")\n}\n\n/// Detalle de repuestos y piezas por orden de mantenimiento (AlmacÃ©n de Mantenimiento)\nmodel DetalleRepuesto {\n  id                   String   @id @default(uuid())\n  ordenMantenimientoId String   @map(\"orden_mantenimiento_id\")\n  descripcion          String   @db.VarChar(255)\n  /// NÃºmero de parte segÃºn catÃ¡logo del fabricante\n  numeroParteCatalogo  String?  @map(\"numero_parte_catalogo\") @db.VarChar(80)\n  unidadMedida         String   @default(\"unidad\") @map(\"unidad_medida\") @db.VarChar(30)\n  cantidad             Decimal  @db.Decimal(10, 3)\n  precioUnitario       Decimal  @map(\"precio_unitario\") @db.Decimal(10, 2)\n  subtotal             Decimal  @db.Decimal(12, 2)\n  /// Indica si el repuesto proviene del AlmacÃ©n de Mantenimiento propio\n  esAlmacenPropio      Boolean  @default(true) @map(\"es_almacen_propio\")\n  proveedor            String?  @db.VarChar(150)\n  creadoEn             DateTime @default(now()) @map(\"creado_en\")\n\n  ordenMantenimiento OrdenMantenimiento @relation(fields: [ordenMantenimientoId], references: [id], onDelete: Cascade)\n\n  @@index([ordenMantenimientoId])\n  @@map(\"detalle_repuestos\")\n}\n\n/// Detalle de mano de obra por tÃ©cnico â€” vinculado a Tarjeta de Mano de Obra\nmodel DetalleManoObra {\n  id                   String   @id @default(uuid())\n  ordenMantenimientoId String   @map(\"orden_mantenimiento_id\")\n  descripcionTarea     String   @map(\"descripcion_tarea\") @db.VarChar(255)\n  horasTrabajadas      Decimal  @map(\"horas_trabajadas\") @db.Decimal(6, 2)\n  costoHora            Decimal  @map(\"costo_hora\") @db.Decimal(8, 2)\n  subtotal             Decimal  @db.Decimal(10, 2)\n  /// Nombre del tÃ©cnico ejecutor (puede ser de taller propio o externo)\n  nombreTecnico        String?  @map(\"nombre_tecnico\") @db.VarChar(100)\n  creadoEn             DateTime @default(now()) @map(\"creado_en\")\n\n  ordenMantenimiento OrdenMantenimiento @relation(fields: [ordenMantenimientoId], references: [id], onDelete: Cascade)\n\n  @@index([ordenMantenimientoId])\n  @@map(\"detalle_mano_obra\")\n}\n\n/// Tipo de mantenimiento (MA 122 02 01)\nenum TipoMantenimiento {\n  PREVENTIVO\n  CORRECTIVO\n}\n\n/// Origen del servicio de mantenimiento\n/// PROPIO: Taller propio (vinculado a Tarjeta de Mano de Obra)\n/// TERCEROS: Taller externo (vinculado a AutorizaciÃ³n de Servicio Externo)\nenum TipoTaller {\n  PROPIO\n  TERCEROS\n}\n\n/// Estado de la orden de mantenimiento\nenum EstadoMantenimiento {\n  PENDIENTE\n  EN_PROCESO\n  COMPLETADO\n  CANCELADO\n}\n\nmodel AsignacionVehiculo {\n  id              String    @id @default(uuid())\n  vehiculoId      String    @map(\"vehiculo_id\")\n  conductorId     String    @map(\"conductor_id\")\n  sectorAsignado  String    @map(\"sector_asignado\") @db.VarChar(150)\n  fechaAsignacion DateTime  @default(now()) @map(\"fecha_asignacion\")\n  fechaFin        DateTime? @map(\"fecha_fin\")\n  activa          Boolean   @default(true)\n  observaciones   String?\n  creadoEn        DateTime  @default(now()) @map(\"creado_en\")\n\n  vehiculo  Vehiculo @relation(fields: [vehiculoId], references: [id])\n  conductor Usuario  @relation(fields: [conductorId], references: [id])\n\n  @@index([vehiculoId])\n  @@index([conductorId])\n  @@index([activa])\n  @@map(\"asignaciones_vehiculos\")\n}\n\nmodel DocumentoVehiculo {\n  id               String        @id @default(uuid())\n  vehiculoId       String        @map(\"vehiculo_id\")\n  tipoDocumento    TipoDocumento @map(\"tipo_documento\")\n  numeroDocumento  String        @map(\"numero_documento\") @db.VarChar(50)\n  fechaEmision     DateTime      @map(\"fecha_emision\")\n  fechaVencimiento DateTime?     @map(\"fecha_vencimiento\")\n  entidadEmisora   String?       @map(\"entidad_emisora\") @db.VarChar(150)\n  observaciones    String?\n  creadoEn         DateTime      @default(now()) @map(\"creado_en\")\n\n  vehiculo Vehiculo @relation(fields: [vehiculoId], references: [id])\n\n  @@index([vehiculoId])\n  @@index([tipoDocumento])\n  @@index([fechaVencimiento])\n  @@map(\"documentos_vehiculo\")\n}\n\nenum TipoDocumento {\n  LICENCIA\n  SOAT\n  REVISION_TECNICA\n  SEGURO\n  TARJETA_PROPIEDAD\n  OTRO\n}\n\n// ============================================================\n// SAF - Sistema de Administración de Flotas\n// Manual F1T02 — Procedimientos Básicos de Operación y Control\n// Archivo: mantenimiento.prisma — Almacén de Mantenimiento\n// ============================================================\n\n/// Repuesto del Almacén de Mantenimiento — MA 122 02 01\nmodel Repuesto {\n  id             String   @id @default(uuid())\n  /// Código único del repuesto en el almacén\n  codigo         String   @unique @db.VarChar(50)\n  descripcion    String   @db.VarChar(255)\n  categoria      String   @db.VarChar(50)\n  unidadMedida   String   @default(\"unidad\") @map(\"unidad_medida\") @db.VarChar(30)\n  stockActual    Int      @default(0) @map(\"stock_actual\")\n  stockMinimo    Int      @default(0) @map(\"stock_minimo\")\n  precioUnitario Decimal? @map(\"precio_unitario\") @db.Decimal(10, 2)\n  creadoEn       DateTime @default(now()) @map(\"creado_en\")\n\n  movimientos MovimientoAlmacen[]\n\n  @@map(\"repuestos\")\n}\n\n/// Movimiento de entrada/salida en el Almacén de Mantenimiento\nmodel MovimientoAlmacen {\n  id                   String   @id @default(uuid())\n  repuestoId           String   @map(\"repuesto_id\")\n  tipoMovimiento       String   @map(\"tipo_movimiento\")\n  cantidad             Int\n  ordenMantenimientoId String?  @map(\"orden_mantenimiento_id\")\n  responsable          String   @db.VarChar(100)\n  fecha                DateTime @default(now())\n  observaciones        String?\n\n  repuesto Repuesto @relation(fields: [repuestoId], references: [id])\n\n  @@index([repuestoId])\n  @@index([fecha])\n  @@map(\"movimientos_almacen\")\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: movimientos_diarios.prisma â€” Esquema de Movimientos Diarios y Checklist\n// ============================================================\n\n/// Registro de uso diario del vehÃ­culo â€” Formulario MA 122 01 01\nmodel MovimientoDiario {\n  id                String   @id @default(uuid())\n  vehiculoId        String   @map(\"vehiculo_id\")\n  conductorId       String   @map(\"conductor_id\")\n  /// Inspector que valida el checklist pre-operacional\n  inspectorId       String?  @map(\"inspector_id\")\n  fecha             DateTime @db.Date\n  sectorSolicitante String   @map(\"sector_solicitante\") @db.VarChar(150)\n  destino           String   @db.VarChar(200)\n  proposito         String?  @db.VarChar(255)\n\n  // â”€â”€ OdÃ³metro â”€â”€\n  kilometrajeSalida    Int  @map(\"kilometraje_salida\")\n  kilometrajeLlegada   Int? @map(\"kilometraje_llegada\")\n  /// Km recorridos en el dÃ­a = kmLlegada - kmSalida (calculado)\n  kilometrajeRecorrido Int? @map(\"kilometraje_recorrido\")\n\n  // â”€â”€ Horas de UtilizaciÃ³n del VehÃ­culo (HUV) â”€â”€\n  /// Hora de salida del vehÃ­culo (formato HH:MM)\n  horaSalida       String   @map(\"hora_salida\") @db.VarChar(5)\n  /// Hora de llegada del vehÃ­culo (formato HH:MM)\n  horaLlegada      String?  @map(\"hora_llegada\") @db.VarChar(5)\n  /// Horas efectivas de utilizaciÃ³n del vehÃ­culo en el dÃ­a\n  horasUtilizacion Decimal? @map(\"horas_utilizacion\") @db.Decimal(5, 2)\n\n  // ── Firmas Digitales ──\n  firmaConductor       String?   @map(\"firma_conductor\") @db.VarChar(100)\n  firmaInspector       String?   @map(\"firma_inspector\") @db.VarChar(100)\n  firmaEncargadoGaraje String?   @map(\"firma_encargado_garaje\") @db.VarChar(100)\n  fechaFirmaConductor  DateTime? @map(\"fecha_firma_conductor\")\n  fechaFirmaInspector  DateTime? @map(\"fecha_firma_inspector\")\n\n  // â”€â”€ Estado â”€â”€\n  estado        EstadoMovimiento @default(EN_RUTA)\n  observaciones String?\n  rutaId        String?          @map(\"ruta_id\")\n  creadoEn      DateTime         @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime         @updatedAt @map(\"actualizado_en\")\n\n  // â”€â”€ Relaciones â”€â”€\n  vehiculo  Vehiculo               @relation(fields: [vehiculoId], references: [id], onDelete: Restrict)\n  conductor Usuario                @relation(\"ConductorMovimiento\", fields: [conductorId], references: [id], onDelete: Restrict)\n  inspector Usuario?               @relation(\"InspectorMovimiento\", fields: [inspectorId], references: [id], onDelete: Restrict)\n  checklist ChecklistVerificacion?\n  ruta      Ruta?                  @relation(fields: [rutaId], references: [id], onDelete: SetNull)\n\n  @@index([vehiculoId])\n  @@index([vehiculoId, fecha])\n  @@index([vehiculoId, estado])\n  @@index([conductorId])\n  @@index([conductorId, fecha])\n  @@index([fecha])\n  @@index([estado])\n  @@map(\"movimientos_diarios\")\n}\n\n/// Checklist de verificaciÃ³n diaria pre-operacional (15 puntos â€” MA 122 01 01)\nmodel ChecklistVerificacion {\n  id           String @id @default(uuid())\n  movimientoId String @unique @map(\"movimiento_id\")\n\n  // â”€â”€ Punto 1: Documentos del vehÃ­culo â”€â”€\n  documentos       EstadoChecklist @default(OK)\n  observDocumentos String?         @map(\"observ_documentos\")\n\n  // â”€â”€ Punto 2: Nivel de aceite de motor â”€â”€\n  aceiteMotor       EstadoChecklist @default(OK) @map(\"aceite_motor\")\n  observAceiteMotor String?         @map(\"observ_aceite_motor\")\n\n  // â”€â”€ Punto 3: Nivel de agua del radiador â”€â”€\n  agua       EstadoChecklist @default(OK)\n  observAgua String?         @map(\"observ_agua\")\n\n  // â”€â”€ Punto 4: BaterÃ­a (nivel de electrolito, bornes) â”€â”€\n  bateria       EstadoChecklist @default(OK)\n  observBateria String?         @map(\"observ_bateria\")\n\n  // â”€â”€ Punto 5: Sistema de frenos (lÃ­quido y funcionamiento) â”€â”€\n  frenos       EstadoChecklist @default(OK)\n  observFrenos String?         @map(\"observ_frenos\")\n\n  // â”€â”€ Punto 6: Embrague (lÃ­quido y funcionamiento) â”€â”€\n  embrague       EstadoChecklist @default(OK)\n  observEmbrague String?         @map(\"observ_embrague\")\n\n  // â”€â”€ Punto 7: Fajas / Correas (alternador, distribuciÃ³n) â”€â”€\n  fajas       EstadoChecklist @default(OK)\n  observFajas String?         @map(\"observ_fajas\")\n\n  // â”€â”€ Punto 8: Faros (delanteros, traseros, de freno) â”€â”€\n  faros       EstadoChecklist @default(OK)\n  observFaros String?         @map(\"observ_faros\")\n\n  // â”€â”€ Punto 9: Lunas / Vidrios â”€â”€\n  lunas       EstadoChecklist @default(OK)\n  observLunas String?         @map(\"observ_lunas\")\n\n  // â”€â”€ Punto 10: Plumillas / Limpiaparabrisas â”€â”€\n  plumillas       EstadoChecklist @default(OK)\n  observPlumillas String?         @map(\"observ_plumillas\")\n\n  // â”€â”€ Punto 11: PresiÃ³n y estado de llantas â”€â”€\n  llantas       EstadoChecklist @default(OK)\n  observLlantas String?         @map(\"observ_llantas\")\n\n  // â”€â”€ Punto 12: Espejos retrovisores â”€â”€\n  espejos       EstadoChecklist @default(OK)\n  observEspejos String?         @map(\"observ_espejos\")\n\n  // â”€â”€ Punto 13: Herramientas y equipo de emergencia â”€â”€\n  herramientas       EstadoChecklist @default(OK)\n  observHerramientas String?         @map(\"observ_herramientas\")\n\n  // â”€â”€ Punto 14: Extintor y botiquÃ­n â”€â”€\n  extintorBotiquin       EstadoChecklist @default(OK) @map(\"extintor_botiquin\")\n  observExtintorBotiquin String?         @map(\"observ_extintor_botiquin\")\n\n  // â”€â”€ Punto 15: Manchas por fugas en el estacionamiento â”€â”€\n  manchasFugas       EstadoChecklist @default(OK) @map(\"manchas_fugas\")\n  observManchasFugas String?         @map(\"observ_manchas_fugas\")\n\n  // â”€â”€ Resultado General â”€â”€\n  aptoParaOperar         Boolean  @default(true) @map(\"apto_para_operar\")\n  observacionesGenerales String?  @map(\"observaciones_generales\")\n  firmaConductor         String?  @map(\"firma_conductor\") @db.VarChar(100)\n  firmaInspector         String?  @map(\"firma_inspector\") @db.VarChar(100)\n  fechaRegistro          DateTime @default(now()) @map(\"fecha_registro\")\n\n  movimiento MovimientoDiario @relation(fields: [movimientoId], references: [id], onDelete: Cascade)\n\n  @@map(\"checklist_verificacion\")\n}\n\n/// Estado del movimiento diario del vehÃ­culo\nenum EstadoMovimiento {\n  PROGRAMADO\n  EN_RUTA\n  COMPLETADO\n  CANCELADO\n}\n\n/// Estado de cada punto del checklist de verificaciÃ³n\nenum EstadoChecklist {\n  OK\n  OBSERVADO\n  FALLADO\n}\n\n// ============================================================\n// SAF - Sistema de Administración de Flotas\n// Archivo: operacion.prisma — Esquema de Rutas y Programación\n// ============================================================\n\n/// Ruta predefinida del sistema de transporte — Origen/Destino\nmodel Ruta {\n  id             String   @id @default(uuid())\n  nombre         String   @db.VarChar(150)\n  origen         String   @db.VarChar(200)\n  destino        String   @db.VarChar(200)\n  distanciaKm    Decimal? @map(\"distancia_km\") @db.Decimal(8, 2)\n  tiempoEstimado String?  @map(\"tiempo_estimado\") @db.VarChar(20)\n  activa         Boolean  @default(true)\n  creadoEn       DateTime @default(now()) @map(\"creado_en\")\n\n  movimientos    MovimientoDiario[]\n  programaciones ProgramacionRuta[]\n\n  @@map(\"rutas\")\n}\n\n/// Programación de viajes: asigna un vehículo y conductor a una ruta en una fecha/hora\nmodel ProgramacionRuta {\n  id            String   @id @default(uuid())\n  rutaId        String   @map(\"ruta_id\")\n  vehiculoId    String   @map(\"vehiculo_id\")\n  conductorId   String   @map(\"conductor_id\")\n  fecha         DateTime @db.Date\n  horaSalida    String   @map(\"hora_salida\") @db.VarChar(5)\n  horaLlegada   String?  @map(\"hora_llegada\") @db.VarChar(5)\n  estado        String   @default(\"PROGRAMADO\")\n  observaciones String?\n  creadoEn      DateTime @default(now()) @map(\"creado_en\")\n\n  ruta      Ruta     @relation(fields: [rutaId], references: [id], onDelete: Restrict)\n  vehiculo  Vehiculo @relation(fields: [vehiculoId], references: [id], onDelete: Restrict)\n  conductor Usuario  @relation(fields: [conductorId], references: [id], onDelete: Restrict)\n\n  @@index([fecha])\n  @@index([vehiculoId])\n  @@index([conductorId])\n  @@map(\"programacion_rutas\")\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Manual F1T02 â€” Procedimientos BÃ¡sicos de OperaciÃ³n y Control\n// Archivo: seguridad.prisma â€” Seguridad y AuditorÃ­a del Sistema\n// ============================================================\n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n// MODELO: Permiso â€” Control granular por mÃ³dulo y acciÃ³n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n/// Permisos granulares del sistema SAF (mÃ³dulo + acciÃ³n)\nmodel Permiso {\n  id          String           @id @default(uuid())\n  modulo      String           @db.VarChar(50)\n  accion      String           @db.VarChar(50)\n  descripcion String?\n  creadoEn    DateTime         @default(now()) @map(\"creado_en\")\n  usuarios    PermisoUsuario[]\n\n  @@unique([modulo, accion])\n  @@map(\"permisos\")\n}\n\n/// Tabla pivote: asignaciÃ³n de permisos a usuarios\nmodel PermisoUsuario {\n  id         String   @id @default(uuid())\n  usuarioId  String   @map(\"usuario_id\")\n  permisoId  String   @map(\"permiso_id\")\n  otorgadoEn DateTime @default(now()) @map(\"otorgado_en\")\n  permiso    Permiso  @relation(fields: [permisoId], references: [id], onDelete: Cascade)\n  usuario    Usuario  @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  @@unique([usuarioId, permisoId])\n  @@index([usuarioId])\n  @@index([permisoId])\n  @@map(\"permisos_usuario\")\n}\n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n// MODELO: SesionAuth â€” Sesiones de autenticaciÃ³n activas\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n/// Sesiones de autenticaciÃ³n activas en el sistema SAF\nmodel SesionAuth {\n  id         String           @id @default(uuid())\n  usuarioId  String           @map(\"usuario_id\")\n  token      String           @unique @db.VarChar(500)\n  ipAddress  String?          @map(\"ip_address\") @db.VarChar(45)\n  userAgent  String?          @map(\"user_agent\")\n  estado     EstadoSesionAuth @default(ACTIVA)\n  iniciadaEn DateTime         @default(now()) @map(\"iniciada_en\")\n  expiraEn   DateTime         @map(\"expira_en\")\n  cerradaEn  DateTime?        @map(\"cerrada_en\")\n  usuario    Usuario          @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  @@index([usuarioId])\n  @@index([token])\n  @@index([estado])\n  @@map(\"sesiones_auth\")\n}\n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n// MODELO: Auditoria â€” Trazabilidad de acciones crÃ­ticas\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n/// Registro de auditorÃ­a: toda acciÃ³n crÃ­tica del sistema SAF\nmodel Auditoria {\n  id           String              @id @default(uuid())\n  usuarioId    String?             @map(\"usuario_id\")\n  accion       TipoAccionAuditoria\n  modulo       String              @db.VarChar(50)\n  entidad      String              @db.VarChar(50)\n  entidadId    String?             @map(\"entidad_id\") @db.VarChar(100)\n  datosAntes   String?             @map(\"datos_antes\")\n  datosDespues String?             @map(\"datos_despues\")\n  ipAddress    String?             @map(\"ip_address\") @db.VarChar(45)\n  descripcion  String?\n  creadoEn     DateTime            @default(now()) @map(\"creado_en\")\n  usuario      Usuario?            @relation(fields: [usuarioId], references: [id], onDelete: SetNull)\n\n  @@index([usuarioId])\n  @@index([accion])\n  @@index([modulo])\n  @@index([creadoEn])\n  @@map(\"auditoria\")\n}\n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n// ENUMs de Seguridad\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n\n/// Estados de una sesiÃ³n de autenticaciÃ³n\nenum EstadoSesionAuth {\n  ACTIVA\n  EXPIRADA\n  CERRADA\n  BLOQUEADA\n}\n\n/// Tipos de acciÃ³n para auditorÃ­a del sistema\nenum TipoAccionAuditoria {\n  LOGIN\n  LOGOUT\n  CREAR\n  ACTUALIZAR\n  ELIMINAR\n  CONSULTAR\n  EXPORTAR\n  CONFIGURAR\n  ALERTA_MANTENIMIENTO\n}\n\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n// MODELO: TokenConfirmacion â€” Tokens para creaciÃ³n/cambio de contraseÃ±a\n// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n/// Tokens de un solo uso para confirmar usuario o cambiar contraseÃ±a\nmodel TokenConfirmacion {\n  id        String    @id @default(uuid())\n  usuarioId String    @map(\"usuario_id\")\n  token     String    @unique @db.VarChar(255)\n  tipo      TipoToken\n  expiraEn  DateTime  @map(\"expira_en\")\n  usadoEn   DateTime? @map(\"usado_en\")\n  creadoEn  DateTime  @default(now()) @map(\"creado_en\")\n  usuario   Usuario   @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  @@index([token])\n  @@index([usuarioId])\n  @@map(\"tokens_confirmacion\")\n}\n\n/// Tipos de token de confirmaciÃ³n\nenum TipoToken {\n  CONFIRMACION_USUARIO\n  CAMBIO_PASSWORD\n}\n\n// ============================================================\n// SAF - Sistema de AdministraciÃ³n de Flotas\n// Archivo: vehiculos.prisma â€” Esquema de VehÃ­culos y Ficha TÃ©cnica\n// ============================================================\n\n/// VehÃ­culo: tabla central del SAF. Ficha tÃ©cnica patrimonial completa (F1T02 Diagrama 3)\nmodel Vehiculo {\n  id String @id @default(uuid())\n\n  // â”€â”€ IdentificaciÃ³n Patrimonial (CÃ³digo 6 dÃ­gitos: CL-CAT-SEQ) â”€â”€\n  /// Clase del vehÃ­culo: 01=Terrestre, 02=AcuÃ¡tico, 03=AÃ©reo\n  clasePatrimonial     String            @map(\"clase_patrimonial\") @db.VarChar(2)\n  /// CategorÃ­a: 01=Pasajeros, 02=Carga, 03=Especial\n  categoriaPatrimonial CategoriaVehiculo @map(\"categoria_patrimonial\")\n  /// NÃºmero secuencial dentro de la categorÃ­a (001â€“999)\n  secuencial           String            @db.VarChar(3)\n  /// CÃ³digo patrimonial completo generado: ej. \"010200 3\" â†’ \"01-02-003\"\n  codigoPatrimonial    String            @unique @map(\"codigo_patrimonial\") @db.VarChar(20)\n\n  // â”€â”€ Datos de Registro â”€â”€\n  placa           String  @unique @db.VarChar(10)\n  marca           String  @db.VarChar(80)\n  modelo          String  @db.VarChar(80)\n  anioFabricacion Int     @map(\"anio_fabricacion\")\n  color           String? @db.VarChar(50)\n\n  // â”€â”€ Especificaciones del Motor y Chasis â”€â”€\n  numeroMotor        String?         @unique @map(\"numero_motor\") @db.VarChar(50)\n  numeroChasis       String?         @unique @map(\"numero_chasis\") @db.VarChar(50)\n  potenciaHp         Int?            @map(\"potencia_hp\")\n  cilindraje         Decimal?        @db.Decimal(5, 2)\n  numeroCilindros    Int?            @map(\"numero_cilindros\")\n  tipoCombustible    TipoCombustible @map(\"tipo_combustible\")\n  capacidadTanqueGal Decimal?        @map(\"capacidad_tanque_gal\") @db.Decimal(8, 2)\n\n  // â”€â”€ Capacidades de Carga y Pasajeros â”€â”€\n  capacidadCargaKg   Decimal? @map(\"capacidad_carga_kg\") @db.Decimal(10, 2)\n  capacidadPasajeros Int?     @map(\"capacidad_pasajeros\")\n  pesoNetoKg         Decimal? @map(\"peso_neto_kg\") @db.Decimal(10, 2)\n  pesoBrutoKg        Decimal? @map(\"peso_bruto_kg\") @db.Decimal(10, 2)\n\n  // â”€â”€ Especificaciones ElÃ©ctricas de la BaterÃ­a â”€â”€\n  /// Tipo de baterÃ­a (ej. Plomo-Ãcido, AGM, Gel)\n  bateriaTipo     String? @map(\"bateria_tipo\") @db.VarChar(50)\n  /// NÃºmero de celdas de la baterÃ­a\n  bateriaCeldas   Int?    @map(\"bateria_celdas\")\n  /// Voltaje nominal de la baterÃ­a (6V, 12V, 24V)\n  bateriaVoltios  Int?    @map(\"bateria_voltios\")\n  /// Amperaje/Capacidad en Ah\n  bateriaAmperios Int?    @map(\"bateria_amperios\")\n  /// NÃºmero de baterÃ­as instaladas\n  numeroBaterias  Int?    @default(1) @map(\"numero_baterias\")\n\n  // â”€â”€ ConfiguraciÃ³n de Ejes y Llantas â”€â”€\n  numeroEjes              Int?     @map(\"numero_ejes\")\n  configuracionEjes       String?  @map(\"configuracion_ejes\") @db.VarChar(30)\n  /// NÃºmero total de llantas (incluyendo repuesto)\n  totalLlantas            Int?     @default(4) @map(\"total_llantas\")\n  dimensionLlantaEstandar String?  @map(\"dimension_llanta_estandar\") @db.VarChar(30)\n  presionLlantaDelantera  Decimal? @map(\"presion_llanta_delantera\") @db.Decimal(5, 2)\n  presionLlantaTrasera    Decimal? @map(\"presion_llanta_trasera\") @db.Decimal(5, 2)\n\n  // â”€â”€ Inventario FÃ­sico del VehÃ­culo (Diagrama 3 â€” Estado Visual) â”€â”€\n  /// Estado de la pintura: BUENO / REGULAR / MALO\n  estadoPintura          EstadoFisico? @map(\"estado_pintura\")\n  /// Estado de los faros delanteros\n  estadoFaros            EstadoFisico? @map(\"estado_faros\")\n  /// Estado de las lunas/vidrios\n  estadoLunas            EstadoFisico? @map(\"estado_lunas\")\n  /// Estado de los espejos retrovisores\n  estadoEspejos          EstadoFisico? @map(\"estado_espejos\")\n  /// Estado general de la carrocerÃ­a\n  estadoCarroceria       EstadoFisico? @map(\"estado_carroceria\")\n  /// Inventario de herramientas y accesorios (texto libre o JSON)\n  inventarioHerramientas String?       @map(\"inventario_herramientas\")\n  /// Observaciones generales del estado fÃ­sico\n  observacionesFisicas   String?       @map(\"observaciones_fisicas\")\n\n  // â”€â”€ Costos Fijos del VehÃ­culo â€” Soporte para CKV â”€â”€\n  /// Valor de adquisiciÃ³n del vehÃ­culo (para cÃ¡lculo de depreciaciÃ³n)\n  valorAdquisicion            Decimal? @map(\"valor_adquisicion\") @db.Decimal(14, 2)\n  /// Vida Ãºtil estimada en aÃ±os (para cÃ¡lculo de depreciaciÃ³n)\n  vidaUtilAnios               Int?     @map(\"vida_util_anios\")\n  /// KilÃ³metros anuales de referencia para prorratear depreciaciÃ³n\n  kmAnualesReferencia         Int?     @map(\"km_anuales_referencia\")\n  /// Prima de seguro anual del vehÃ­culo\n  seguroAnual                 Decimal? @map(\"seguro_anual\") @db.Decimal(12, 2)\n  /// Costo anual de licenciamiento y SOAT\n  licenciamientoAnual         Decimal? @map(\"licenciamiento_anual\") @db.Decimal(10, 2)\n  /// Kilometraje en que se activÃ³ la alerta de mantenimiento preventivo\n  kmAlertaMantenimiento       Int?     @map(\"km_alerta_mantenimiento\")\n  /// Periodicidad de mantenimiento preventivo en km (segÃºn fabricante)\n  periodicidadMantenimientoKm Int?     @default(5000) @map(\"periodicidad_mantenimiento_km\")\n\n  // â”€â”€ Estado Operativo â”€â”€\n  estado        EstadoVehiculo @default(OPERATIVO)\n  fechaIngreso  DateTime       @default(now()) @map(\"fecha_ingreso\")\n  fechaBaja     DateTime?      @map(\"fecha_baja\")\n  motivoBaja    String?        @map(\"motivo_baja\")\n  creadoEn      DateTime       @default(now()) @map(\"creado_en\")\n  actualizadoEn DateTime       @updatedAt @map(\"actualizado_en\")\n\n  // â”€â”€ Relaciones â”€â”€\n  movimientosDiarios      MovimientoDiario[]\n  ordenesCombustible      OrdenCombustible[]\n  ordenesMantenimiento    OrdenMantenimiento[]\n  controlLlantas          ControlLlanta[]\n  reportesMensualesCostos ReporteMensualCostos[]\n  desempenoLlantas        DesempenoLlantas[]\n  resumenKpisVehiculo     ResumenKpisVehiculo[]\n  asignaciones            AsignacionVehiculo[]\n  documentos              DocumentoVehiculo[]\n  programaciones          ProgramacionRuta[]\n\n  @@index([placa])\n  @@index([estado])\n  @@index([categoriaPatrimonial])\n  @@index([codigoPatrimonial])\n  @@index([tipoCombustible])\n  @@index([marca, modelo])\n  @@map(\"vehiculos\")\n}\n\n/// CategorÃ­as patrimoniales del vehÃ­culo segÃºn clasificaciÃ³n F1T02\nenum CategoriaVehiculo {\n  PASAJEROS\n  CARGA\n  ESPECIAL\n}\n\n/// Tipos de combustible del vehÃ­culo\nenum TipoCombustible {\n  GASOLINA\n  DIESEL\n  GLP\n  ELECTRICO\n  HIBRIDO\n}\n\n/// Estado operativo del vehÃ­culo\nenum EstadoVehiculo {\n  OPERATIVO\n  EN_MANTENIMIENTO\n  INOPERATIVO\n  DADO_DE_BAJA\n}\n\n/// Estado fÃ­sico de componentes visuales del vehÃ­culo (Diagrama 3)\nenum EstadoFisico {\n  BUENO\n  REGULAR\n  MALO\n}\n"
}

